package dev.dwmir.lib;
import net.fabricmc.fabric.api.client.gametest.v1.*;import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;import net.minecraft.client.MinecraftClient;import net.minecraft.client.gui.*;import net.minecraft.client.gui.screen.Screen;import net.minecraft.client.gui.widget.ClickableWidget;import net.minecraft.client.input.MouseInput;import net.minecraft.item.*;import net.minecraft.block.*;import net.minecraft.util.math.BlockPos;import net.minecraft.entity.player.PlayerEntity;import java.util.*;
public final class R10Checks implements FabricClientGameTest {
 private PlayerEntity target;private final Map<BlockPos,BlockState> wall=new HashMap<>();private void check(boolean b,String reason){if(!b)throw new AssertionError(reason);}private void click(MinecraftClient c,String name){Screen s=WorkspaceScreen.actual(c.currentScreen);var button=s.children().stream().filter(e->e instanceof ClickableWidget w&&w.getMessage().getString().startsWith(name)).map(e->(ClickableWidget)e).findFirst().orElseThrow(()->new AssertionError(name));double x=button.getX()+button.getWidth()/2.,y=button.getY()+button.getHeight()/2.;if(c.currentScreen instanceof WorkspaceScreen w){x=w.screenX(x);y=w.screenY(y);}var event=new Click(x,y,new MouseInput(0,0));check(c.currentScreen.mouseClicked(event,false),"Click rejected "+name);c.currentScreen.mouseReleased(event);}
 private void wall(MinecraftClient c,int height){for(var e:wall.entrySet())c.world.setBlockState(e.getKey(),e.getValue(),3);wall.clear();int x=(int)Math.floor(c.player.getX()),y=(int)Math.floor(c.player.getY()),z=(int)Math.floor(c.player.getZ()+2);for(int xx=-2;xx<=2;xx++)for(int yy=0;yy<height;yy++){var p=new BlockPos(x+xx,y+yy,z);wall.put(p,c.world.getBlockState(p));c.world.setBlockState(p,Blocks.STONE.getDefaultState(),3);}}
 public void runTest(ClientGameTestContext t){new VanillaIconExport().runTest(t);t.getInput().resizeWindow(1440,900);t.runOnClient(c->{LibraryState.accept("library-onboarding-v2");LibraryState.select(LibraryState.Theme.SAKURA);c.options.language="en_us";c.options.getGuiScale().setValue(2);c.onResolutionChanged();check(DwmirLib.settings("playerglowing")!=null&&DwmirLib.settings("betterhighlighter")!=null,"New modules missing");dev.dwmir.glowing.Config.current=new dev.dwmir.glowing.Config();dev.dwmir.highlighter.Config.current=new dev.dwmir.highlighter.Config();dev.dwmir.countit.Config.current=new dev.dwmir.countit.Config();});
 try(var world=t.worldBuilder().create()){world.getClientWorld().waitForChunksRender();t.runOnClient(c->{c.player.setYaw(0);c.player.setPitch(0);c.player.getInventory().setStack(0,ItemStack.EMPTY);c.player.getInventory().setStack(40,ItemStack.EMPTY);var p=new net.minecraft.client.network.OtherClientPlayerEntity(c.world,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"GlowTarget"));p.setId(424250);p.setPosition(c.player.getX(),c.player.getY(),c.player.getZ()+4);p.setYaw(180);c.world.addEntity(p);target=p;var cfg=dev.dwmir.glowing.Config.current;cfg.color=0xff55ff;cfg.targetAccent=false;cfg.reachGlow=false;check(dev.dwmir.glowing.Client.eligible(p),"Visible target rejected");cfg.friends="GlowTarget";check(!dev.dwmir.glowing.Client.eligible(p),"Friend filter");cfg.friends="";cfg.combatOnly=true;check(!dev.dwmir.glowing.Client.eligible(p),"Combat filter without event");c.getNetworkHandler().onEntityDamage(new net.minecraft.network.packet.s2c.play.EntityDamageS2CPacket(p,c.world.getDamageSources().playerAttack(c.player)));check(dev.dwmir.glowing.Client.eligible(p),"Combat event did not enable target");cfg.combatOnly=false;p.setStackInHand(net.minecraft.util.Hand.OFF_HAND,new ItemStack(Items.SHIELD));check(dev.dwmir.glowing.Client.color(p)==cfg.holdingColor,"Held shield color");c.getNetworkHandler().onEntityStatus(new net.minecraft.network.packet.s2c.play.EntityStatusS2CPacket(p,(byte)30));check(dev.dwmir.glowing.Client.color(p)==cfg.brokenColor,"Broken shield packet color");dev.dwmir.glowing.Client.broken.clear();p.setStackInHand(net.minecraft.util.Hand.OFF_HAND,ItemStack.EMPTY);});
 for(int mode=0;mode<2;mode++){final int m=mode;t.setScreen(()->null);t.runOnClient(c->dev.dwmir.glowing.Config.current.mode=m);t.waitTicks(8);t.takeScreenshot("r10-world-glow-"+mode);}
 t.runOnClient(c->{wall(c,3);check(!c.player.canSee(target)&&!dev.dwmir.glowing.Client.eligible(target),"Wall visibility rejected");});t.waitTicks(6);t.takeScreenshot("r10-full-wall");t.runOnClient(c->{wall(c,1);check(c.player.canSee(target)&&dev.dwmir.glowing.Client.eligible(target),"Partial wall should keep head visible");});t.waitTicks(6);t.takeScreenshot("r10-partial-wall");t.runOnClient(c->{wall(c,0);target.setPosition(c.player.getX()+2,c.player.getY(),c.player.getZ()+3);});t.waitTicks(8);t.takeScreenshot("r10-world-direction-left");t.runOnClient(c->target.setPosition(c.player.getX(),c.player.getY(),c.player.getZ()+4));
 t.setScreen(()->new dev.dwmir.glowing.SettingsScreen(null));t.waitTicks(8);t.takeScreenshot("r10-glowing-preview");for(String page:new String[]{"Combat","Direction","Shadow"}){t.runOnClient(c->click(c,page));t.waitTicks(8);t.takeScreenshot("r10-glowing-"+page.toLowerCase());}
 t.runOnClient(c->{var hc=dev.dwmir.highlighter.Config.current;hc.enabled=true;check(dev.dwmir.highlighter.Rules.color(new ItemStack(Items.STONE))==-1,"Unlisted item highlighted");check(dev.dwmir.highlighter.Rules.color(new ItemStack(Items.ENDER_PEARL))==0x13a889,"Pearl rule");var stack=new ItemStack(Items.CROSSBOW);stack.addEnchantment(c.world.getRegistryManager().getOrThrow(net.minecraft.registry.RegistryKeys.ENCHANTMENT).getOrThrow(net.minecraft.enchantment.Enchantments.PIERCING),3);check(dev.dwmir.highlighter.Rules.color(stack)==0xff0000,"Piercing rule");hc.rules.get("Piercing Crossbow").enabled=false;check(dev.dwmir.highlighter.Rules.color(stack)==-1,"Disabled enchant rule");hc.rules.get("Piercing Crossbow").enabled=true;for(int i=0;i<9;i++)c.player.getInventory().setStack(i,new ItemStack(new Item[]{Items.TOTEM_OF_UNDYING,Items.CROSSBOW,Items.ENDER_PEARL,Items.GOLDEN_APPLE,Items.END_CRYSTAL,Items.MACE,Items.EXPERIENCE_BOTTLE,Items.SHIELD,Items.DIAMOND_SWORD}[i]));});
 for(int style=0;style<10;style++){final int st=style;t.runOnClient(c->dev.dwmir.highlighter.Config.current.animation=st);t.setScreen(()->new dev.dwmir.highlighter.SettingsScreen(null));t.waitTicks(5);t.takeScreenshot("r10-highlight-"+style);}t.setScreen(()->new net.minecraft.client.gui.screen.ingame.InventoryScreen(net.minecraft.client.MinecraftClient.getInstance().player));t.waitTicks(8);t.takeScreenshot("r10-native-inventory-highlight");
 for(int shape=0;shape<11;shape++){final int s=shape;t.setScreen(()->new dev.dwmir.countit.SettingsScreen(null));t.runOnClient(c->{dev.dwmir.countit.Config.current.particleShape=s;click(c,"Particles");});t.waitTicks(6);t.takeScreenshot("r10-particle-preview-"+shape);}
 t.setScreen(()->null);t.runOnClient(c->{dev.dwmir.countit.Config.current.particleShape=1;dev.dwmir.countit.Config.current.particleSize=2;for(int i=0;i<80;i++)c.world.addParticleClient(net.minecraft.particle.ParticleTypes.TOTEM_OF_UNDYING,c.player.getX()+(Math.random()-.5)*2,c.player.getY()+.5+Math.random()*2,c.player.getZ()+2+Math.random(),0,.02,0);});t.waitTicks(3);t.takeScreenshot("r10-world-snowflakes");
 t.waitTicks(80);for(int design:new int[]{6,12,18}){final int value=design;t.runOnClient(c->dev.dwmir.glowing.Config.current.shadowDesign=value);t.waitTicks(4);t.takeScreenshot("r10-world-shadow-"+design);}
 t.runOnClient(c->{dev.dwmir.glowing.Config.current=new dev.dwmir.glowing.Config();dev.dwmir.glowing.Config.save();dev.dwmir.countit.Config.current=new dev.dwmir.countit.Config();dev.dwmir.countit.Config.save();dev.dwmir.highlighter.Config.current=new dev.dwmir.highlighter.Config();dev.dwmir.highlighter.Config.save();});
 t.setScreen(()->new dev.dwmir.sprinter.SettingsScreen(null));t.waitTicks(8);t.takeScreenshot("r10-sprinter-preview");t.setScreen(()->DwmirLib.createScreen(null));t.getInput().setCursorPos(0,0);t.waitTicks(8);t.takeScreenshot("r10-library-eight");}
 t.setScreen(()->null);System.out.println("DWMIR_R10_CHECKS_PASS FRIENDS=OK COMBAT=OK LOS=OK HIGHLIGHT_RULES=OK PREVIEWS=OK");}
}
